namespace MediView.BuildingBlocks.Domain;

public abstract class Entity<TId> where TId : notnull
{
    public TId Id { get; protected set; } = default!;

    public override bool Equals(object? obj) =>
        obj is Entity<TId> other && other.GetType() == GetType() && other.Id.Equals(Id);

    public override int GetHashCode() => Id.GetHashCode();
}

namespace MediView.BuildingBlocks.Domain;

public interface IDomainEvent
{
    DateTimeOffset OccurredOn { get; }
}

namespace MediView.BuildingBlocks.Domain;

public abstract class AggregateRoot<TId> : Entity<TId> where TId : notnull
{
    private readonly List<IDomainEvent> _domainEvents = new();
    public IReadOnlyCollection<IDomainEvent> DomainEvents => _domainEvents.AsReadOnly();

    protected void Raise(IDomainEvent domainEvent) => _domainEvents.Add(domainEvent);
    public void ClearDomainEvents() => _domainEvents.Clear();
}

namespace MediView.BuildingBlocks.Application;

public sealed record Error(string Code, string Message)
{
    public static readonly Error None = new(string.Empty, string.Empty);
}

public class Result
{
    protected Result(bool isSuccess, Error error)
    {
        if (isSuccess && error != Error.None) throw new InvalidOperationException();
        IsSuccess = isSuccess; Error = error;
    }
    public bool IsSuccess { get; }
    public bool IsFailure => !IsSuccess;
    public Error Error { get; }

    public static Result Success() => new(true, Error.None);
    public static Result Failure(Error error) => new(false, error);
    public static Result<T> Success<T>(T value) => new(value, true, Error.None);
    public static Result<T> Failure<T>(Error error) => new(default, false, error);
}

public class Result<T> : Result
{
    private readonly T? _value;
    protected internal Result(T? value, bool isSuccess, Error error) : base(isSuccess, error) => _value = value;
    public T Value => IsSuccess ? _value! : throw new InvalidOperationException("No value on a failure.");
    public static implicit operator Result<T>(T value) => Success(value);
}

namespace MediView.BuildingBlocks.Application;

public interface IRequest<TResponse>;
public interface ICommand<TResponse> : IRequest<TResponse>;
public interface IQuery<TResponse> : IRequest<TResponse>;

public interface IRequestHandler<in TRequest, TResponse> where TRequest : IRequest<TResponse>
{
    Task<TResponse> Handle(TRequest request, CancellationToken ct);
}
public interface ICommandHandler<in TCommand, TResponse> : IRequestHandler<TCommand, TResponse>
    where TCommand : ICommand<TResponse>;
public interface IQueryHandler<in TQuery, TResponse> : IRequestHandler<TQuery, TResponse>
    where TQuery : IQuery<TResponse>;

public interface ISender
{
    Task<TResponse> Send<TResponse>(IRequest<TResponse> request, CancellationToken ct = default);
}

using Microsoft.Extensions.DependencyInjection;
namespace MediView.BuildingBlocks.Application;

internal sealed class Sender(IServiceProvider provider) : ISender
{
    public Task<TResponse> Send<TResponse>(IRequest<TResponse> request, CancellationToken ct = default)
    {
        var handlerType = typeof(IRequestHandler<,>).MakeGenericType(request.GetType(), typeof(TResponse));
        dynamic handler = provider.GetRequiredService(handlerType);
        return handler.Handle((dynamic)request, ct);
    }
}

using System.Reflection;
using Microsoft.Extensions.DependencyInjection;
namespace MediView.BuildingBlocks.Application;

public static class DependencyInjection
{
    public static IServiceCollection AddApplication(this IServiceCollection services, Assembly assembly)
    {
        services.AddScoped<ISender, Sender>();
        var handlerInterface = typeof(IRequestHandler<,>);
        foreach (var type in assembly.GetTypes().Where(t => t is { IsAbstract: false, IsInterface: false }))
            foreach (var i in type.GetInterfaces().Where(i => i.IsGenericType && i.GetGenericTypeDefinition() == handlerInterface))
                services.AddScoped(i, type);
        return services;
    }
}

using FluentValidation;
namespace MediView.BuildingBlocks.Application.Behaviours;

public interface IPipelineBehaviour<TRequest, TResponse>
{
    Task<TResponse> Handle(TRequest request, Func<Task<TResponse>> next, CancellationToken ct);
}

public sealed class ValidationBehaviour<TRequest, TResponse>(IEnumerable<IValidator<TRequest>> validators)
    : IPipelineBehaviour<TRequest, TResponse>
{
    public async Task<TResponse> Handle(TRequest request, Func<Task<TResponse>> next, CancellationToken ct)
    {
        var context = new ValidationContext<TRequest>(request);
        var failures = validators
            .Select(v => v.Validate(context))
            .SelectMany(r => r.Errors)
            .Where(f => f is not null)
            .ToList();
        if (failures.Count != 0)
            throw new ValidationException(failures);   // mapped to 400 by ExceptionHandlingMiddleware
        return await next();
    }
}

using System.Diagnostics;
using Microsoft.Extensions.Logging;
namespace MediView.BuildingBlocks.Application.Behaviours;

public sealed class LoggingBehaviour<TRequest, TResponse>(ILogger<LoggingBehaviour<TRequest, TResponse>> logger)
    : IPipelineBehaviour<TRequest, TResponse>
{
    public async Task<TResponse> Handle(TRequest request, Func<Task<TResponse>> next, CancellationToken ct)
    {
        var name = typeof(TRequest).Name;
        var sw = Stopwatch.StartNew();
        try
        {
            var response = await next();
            logger.LogInformation("Handled {RequestName} in {ElapsedMs}ms ({Outcome})", name, sw.ElapsedMilliseconds, "ok");
            return response;
        }
        catch
        {
            logger.LogWarning("Failed {RequestName} in {ElapsedMs}ms ({Outcome})", name, sw.ElapsedMilliseconds, "error");
            throw;
        }
    }
}

using Microsoft.AspNetCore.Http;
using Serilog.Context;
namespace MediView.BuildingBlocks.Api;

public sealed class CorrelationIdMiddleware(RequestDelegate next)
{
    private const string Header = "X-Correlation-Id";
    public async Task Invoke(HttpContext ctx)
    {
        var id = ctx.Request.Headers.TryGetValue(Header, out var v) && !string.IsNullOrWhiteSpace(v)
            ? v.ToString() : Guid.NewGuid().ToString("N");
        ctx.Response.Headers[Header] = id;
        using (LogContext.PushProperty("CorrelationId", id))
            await next(ctx);
    }
}

using FluentValidation;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using MediView.BuildingBlocks.Domain;
namespace MediView.BuildingBlocks.Api;

public sealed class ExceptionHandlingMiddleware(RequestDelegate next)
{
    public async Task Invoke(HttpContext ctx)
    {
        try { await next(ctx); }
        catch (Exception ex)
        {
            var (status, title) = ex switch
            {
                ValidationException            => (400, "Validation failed"),
                DomainException                => (400, "Domain rule violated"),
                // NotFoundException            => (404, "Not found"),
                // StudyLockedException         => (409, "Study is locked"),
                // DbUpdateConcurrencyException => (409, "Concurrency conflict"),
                _                              => (500, "Unexpected error")
            };
            var problem = new ProblemDetails { Status = status, Title = title,
                Detail = status == 500 ? "An unexpected error occurred." : ex.Message };
            problem.Extensions["correlationId"] = ctx.Response.Headers["X-Correlation-Id"].ToString();
            ctx.Response.StatusCode = status;
            await ctx.Response.WriteAsJsonAsync(problem);
        }
    }
}

using Microsoft.AspNetCore.Builder;
namespace MediView.BuildingBlocks.Api;

public static class ApiDefaults
{
    public static WebApplication UseApiDefaults(this WebApplication app)
    {
        app.UseMiddleware<CorrelationIdMiddleware>();     // first: id is available to everything after
        app.UseMiddleware<ExceptionHandlingMiddleware>();
        return app;
    }
}

